import{_ as e,o as r,c as h,a3 as t}from"./chunks/framework.D8u9WiMi.js";const u=JSON.parse('{"title":"AI公众号内容矩阵执行手册（高密度版）","description":"","frontmatter":{},"headers":[],"relativePath":"examples/idea/AI公众号内容矩阵执行说明（完整版）.md","filePath":"examples/idea/AI公众号内容矩阵执行说明（完整版）.md"}'),i={name:"examples/idea/AI公众号内容矩阵执行说明（完整版）.md"};function l(o,a,n,d,s,p){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="ai公众号内容矩阵执行手册-高密度版" tabindex="-1">AI公众号内容矩阵执行手册（高密度版） <a class="header-anchor" href="#ai公众号内容矩阵执行手册-高密度版" aria-label="Permalink to &quot;AI公众号内容矩阵执行手册（高密度版）&quot;">​</a></h1><hr><h2 id="🧠-一、整体运营逻辑-必须先理解" tabindex="-1">🧠 一、整体运营逻辑（必须先理解） <a class="header-anchor" href="#🧠-一、整体运营逻辑-必须先理解" aria-label="Permalink to &quot;🧠 一、整体运营逻辑（必须先理解）&quot;">​</a></h2><p>这套矩阵的核心不是“写文章”，而是<strong>搭建一个内容转化系统</strong>：先用趋势内容抓用户的注意力，让他意识到AI和自己有关；再用教程让他觉得“这个号有用”；再通过案例建立信任，让用户相信“别人真的做到了”；接着用赚钱/提效内容引导用户产生行动；最后通过避坑内容建立长期信任，让用户愿意持续关注你。</p><p>一句话总结：<strong>你不是在做内容，而是在做用户认知升级路径。</strong></p><hr><h1 id="🧩-二、栏目一-ai趋势观察-流量入口模块" tabindex="-1">🧩 二、栏目一：AI趋势观察（流量入口模块） <a class="header-anchor" href="#🧩-二、栏目一-ai趋势观察-流量入口模块" aria-label="Permalink to &quot;🧩 二、栏目一：AI趋势观察（流量入口模块）&quot;">​</a></h1><h2 id="🎯-目标" tabindex="-1">🎯 目标 <a class="header-anchor" href="#🎯-目标" aria-label="Permalink to &quot;🎯 目标&quot;">​</a></h2><p>快速吸引点击，让用户产生“我必须了解AI”的心理，同时建立你“懂行业”的人设。</p><h2 id="🛠-执行步骤-标准流程" tabindex="-1">🛠 执行步骤（标准流程） <a class="header-anchor" href="#🛠-执行步骤-标准流程" aria-label="Permalink to &quot;🛠 执行步骤（标准流程）&quot;">​</a></h2><p>每天固定时间（建议上午或中午）做一轮信息收集，来源包括：Twitter（AI领域账号）、Product Hunt、Hacker News、知乎热榜、小红书AI标签、B站科技区；重点不是看技术，而是找“变化点”，例如：某个AI突然能做以前做不了的事情、某个公司开始用AI替代岗位、某个功能引发大规模讨论。</p><p>找到变化点后，用一个关键动作完成内容转化：<strong>把“技术变化”翻译成“普通人影响”</strong>。 例如：“AI Agent发布” → 改写为“AI开始自己干活，不再需要人操作”。</p><h2 id="📌-写作结构-固定模板" tabindex="-1">📌 写作结构（固定模板） <a class="header-anchor" href="#📌-写作结构-固定模板" aria-label="Permalink to &quot;📌 写作结构（固定模板）&quot;">​</a></h2><p>开头必须用“共鸣 + 提问”形式引入（你有没有发现最近…）；中间用真实案例或现象解释发生了什么变化；重点部分讲清楚这个变化对普通人的影响（比如工作、收入、技能）；结尾给出简单建议（比如你应该开始学什么）。</p><h2 id="📌-选题方向-长期使用" tabindex="-1">📌 选题方向（长期使用） <a class="header-anchor" href="#📌-选题方向-长期使用" aria-label="Permalink to &quot;📌 选题方向（长期使用）&quot;">​</a></h2><p>围绕三个方向持续输出： 1）岗位变化（谁被替代） 2）能力变化（什么能力更值钱） 3）行业变化（哪个行业正在被AI改造）</p><h2 id="⚠️-注意点" tabindex="-1">⚠️ 注意点 <a class="header-anchor" href="#⚠️-注意点" aria-label="Permalink to &quot;⚠️ 注意点&quot;">​</a></h2><p>不要写成新闻搬运，不要用专业术语堆砌，一定要用“普通人视角”，否则点击率会很低。</p><hr><h1 id="🧩-三、栏目二-ai实用教程-收藏核心模块" tabindex="-1">🧩 三、栏目二：AI实用教程（收藏核心模块） <a class="header-anchor" href="#🧩-三、栏目二-ai实用教程-收藏核心模块" aria-label="Permalink to &quot;🧩 三、栏目二：AI实用教程（收藏核心模块）&quot;">​</a></h1><h2 id="🎯-目标-1" tabindex="-1">🎯 目标 <a class="header-anchor" href="#🎯-目标-1" aria-label="Permalink to &quot;🎯 目标&quot;">​</a></h2><p>让用户产生“这篇文章对我有用，我要收藏”的行为，提高账号权重和粘性。</p><h2 id="🛠-执行步骤" tabindex="-1">🛠 执行步骤 <a class="header-anchor" href="#🛠-执行步骤" aria-label="Permalink to &quot;🛠 执行步骤&quot;">​</a></h2><p>先选一个具体场景（例如写公众号、做PPT、写周报、做短视频），然后用AI工具完整跑一遍流程，把过程中每一步记录下来，重点是“你是怎么提问的”“AI给了什么结果”“你如何优化”。</p><p>完成之后，把流程拆成清晰步骤：输入什么 → 输出什么 → 怎么调整。 再补充一段“提示词模板”，让用户可以直接复制使用。</p><h2 id="📌-内容结构-必须严格执行" tabindex="-1">📌 内容结构（必须严格执行） <a class="header-anchor" href="#📌-内容结构-必须严格执行" aria-label="Permalink to &quot;📌 内容结构（必须严格执行）&quot;">​</a></h2><p>开头直接说明结果（例如：我用AI写了一篇文章，只用了10分钟）；中间分步骤讲清楚流程（步骤1、2、3）；附上完整提示词；展示最终效果（截图或示例）；结尾说明适用人群。</p><h2 id="📌-选题方向" tabindex="-1">📌 选题方向 <a class="header-anchor" href="#📌-选题方向" aria-label="Permalink to &quot;📌 选题方向&quot;">​</a></h2><p>围绕“替代重复劳动”展开： 写作、总结、翻译、设计、剪辑、办公自动化。</p><h2 id="⚠️-注意点-1" tabindex="-1">⚠️ 注意点 <a class="header-anchor" href="#⚠️-注意点-1" aria-label="Permalink to &quot;⚠️ 注意点&quot;">​</a></h2><p>不要讲原理，只讲操作；不要讲“为什么这样做”，而是讲“你照着做就行”；教程越简单越好，越复杂越没人看。</p><hr><h1 id="🧩-四、栏目三-ai案例拆解-信任建立模块" tabindex="-1">🧩 四、栏目三：AI案例拆解（信任建立模块） <a class="header-anchor" href="#🧩-四、栏目三-ai案例拆解-信任建立模块" aria-label="Permalink to &quot;🧩 四、栏目三：AI案例拆解（信任建立模块）&quot;">​</a></h1><h2 id="🎯-目标-2" tabindex="-1">🎯 目标 <a class="header-anchor" href="#🎯-目标-2" aria-label="Permalink to &quot;🎯 目标&quot;">​</a></h2><p>让用户相信“AI不是概念，而是真实发生的事情”，增强账号可信度。</p><h2 id="🛠-执行步骤-1" tabindex="-1">🛠 执行步骤 <a class="header-anchor" href="#🛠-执行步骤-1" aria-label="Permalink to &quot;🛠 执行步骤&quot;">​</a></h2><p>收集真实案例（可以来自新闻、社交媒体、行业报告，也可以是你自己或身边人的实践），筛选标准只有一个：<strong>有没有具体结果</strong>（比如节省时间、赚到钱、提高效率）。</p><p>写作时，不要泛讲，一定要拆解清楚： 是谁（背景）→ 做了什么（行为）→ 用了什么AI（工具/方法）→ 结果如何（数据/变化）→ 普通人能不能复用。</p><h2 id="📌-内容结构" tabindex="-1">📌 内容结构 <a class="header-anchor" href="#📌-内容结构" aria-label="Permalink to &quot;📌 内容结构&quot;">​</a></h2><p>开头直接讲结果（例如：一个人用AI做内容，一个月涨粉10万）；中间讲过程（他怎么做的）；最后总结方法（你可以怎么做）。</p><h2 id="📌-选题方向-1" tabindex="-1">📌 选题方向 <a class="header-anchor" href="#📌-选题方向-1" aria-label="Permalink to &quot;📌 选题方向&quot;">​</a></h2><p>企业应用（客服、营销、招聘）、个人副业、自媒体、办公效率、行业变化。</p><h2 id="⚠️-注意点-2" tabindex="-1">⚠️ 注意点 <a class="header-anchor" href="#⚠️-注意点-2" aria-label="Permalink to &quot;⚠️ 注意点&quot;">​</a></h2><p>案例一定要具体，不能写“很多人都在用AI”，必须写“某个人做了什么”；没有数据就用对比（以前 vs 现在）。</p><hr><h1 id="🧩-五、栏目四-ai赚钱-提效-转化核心模块" tabindex="-1">🧩 五、栏目四：AI赚钱 / 提效（转化核心模块） <a class="header-anchor" href="#🧩-五、栏目四-ai赚钱-提效-转化核心模块" aria-label="Permalink to &quot;🧩 五、栏目四：AI赚钱 / 提效（转化核心模块）&quot;">​</a></h1><h2 id="🎯-目标-3" tabindex="-1">🎯 目标 <a class="header-anchor" href="#🎯-目标-3" aria-label="Permalink to &quot;🎯 目标&quot;">​</a></h2><p>让用户产生“我要用AI赚钱/提升效率”的行动欲望，是账号变现的关键内容。</p><h2 id="🛠-执行步骤-2" tabindex="-1">🛠 执行步骤 <a class="header-anchor" href="#🛠-执行步骤-2" aria-label="Permalink to &quot;🛠 执行步骤&quot;">​</a></h2><p>围绕“赚钱”和“节省时间”两个核心，拆出具体路径，例如： 写作接单、短视频、信息差、工具服务、代运营、自动化办公。</p><p>写作时一定要给“路径”，而不是讲道理： 第一步做什么 → 第二步做什么 → 第三步如何变现。</p><h2 id="📌-内容结构-1" tabindex="-1">📌 内容结构 <a class="header-anchor" href="#📌-内容结构-1" aria-label="Permalink to &quot;📌 内容结构&quot;">​</a></h2><p>开头提出问题（你现在不赚钱/很忙）；中间给出解决方案（AI）；然后拆步骤；最后给结果（赚多少钱或节省多少时间）。</p><h2 id="📌-选题方向-2" tabindex="-1">📌 选题方向 <a class="header-anchor" href="#📌-选题方向-2" aria-label="Permalink to &quot;📌 选题方向&quot;">​</a></h2><p>副业项目、接单路径、效率工具、自动化流程、AI工作流。</p><h2 id="⚠️-注意点-3" tabindex="-1">⚠️ 注意点 <a class="header-anchor" href="#⚠️-注意点-3" aria-label="Permalink to &quot;⚠️ 注意点&quot;">​</a></h2><p>不要夸大收益，不要讲“轻松月入10万”，容易被判低质；要强调“可复制的小结果”，比如“多赚一笔”“省2小时”。</p><hr><h1 id="🧩-六、栏目五-ai避坑-辟谣-信任加固模块" tabindex="-1">🧩 六、栏目五：AI避坑 / 辟谣（信任加固模块） <a class="header-anchor" href="#🧩-六、栏目五-ai避坑-辟谣-信任加固模块" aria-label="Permalink to &quot;🧩 六、栏目五：AI避坑 / 辟谣（信任加固模块）&quot;">​</a></h1><h2 id="🎯-目标-4" tabindex="-1">🎯 目标 <a class="header-anchor" href="#🎯-目标-4" aria-label="Permalink to &quot;🎯 目标&quot;">​</a></h2><p>建立长期信任，让用户觉得你是“靠谱的信息源”，提高关注留存。</p><h2 id="🛠-执行步骤-3" tabindex="-1">🛠 执行步骤 <a class="header-anchor" href="#🛠-执行步骤-3" aria-label="Permalink to &quot;🛠 执行步骤&quot;">​</a></h2><p>整理常见误区，例如： 提示词神话、AI副业骗局、版权问题、数据安全问题。</p><p>写作时用“反常识”开头（很多人以为…其实不是）；然后解释为什么错；最后给出正确做法。</p><h2 id="📌-内容结构-2" tabindex="-1">📌 内容结构 <a class="header-anchor" href="#📌-内容结构-2" aria-label="Permalink to &quot;📌 内容结构&quot;">​</a></h2><p>错误认知 → 拆解原因 → 正确方法 → 建议。</p><h2 id="📌-选题方向-3" tabindex="-1">📌 选题方向 <a class="header-anchor" href="#📌-选题方向-3" aria-label="Permalink to &quot;📌 选题方向&quot;">​</a></h2><p>骗局、误区、认知偏差、平台规则、法律风险。</p><h2 id="⚠️-注意点-4" tabindex="-1">⚠️ 注意点 <a class="header-anchor" href="#⚠️-注意点-4" aria-label="Permalink to &quot;⚠️ 注意点&quot;">​</a></h2><p>不要只说“这个不好”，要给替代方案；否则用户看完没有收获。</p><hr><h1 id="📅-七、执行节奏-每周固定" tabindex="-1">📅 七、执行节奏（每周固定） <a class="header-anchor" href="#📅-七、执行节奏-每周固定" aria-label="Permalink to &quot;📅 七、执行节奏（每周固定）&quot;">​</a></h1><p>建议形成固定节奏，让用户形成预期：</p><ul><li>周一：趋势（吸引流量）</li><li>周三：教程（提高收藏）</li><li>周五：案例（建立信任）</li><li>周日：赚钱 / 避坑（转化或增强信任）</li></ul><hr><h1 id="📊-八、数据优化方法-必须做" tabindex="-1">📊 八、数据优化方法（必须做） <a class="header-anchor" href="#📊-八、数据优化方法-必须做" aria-label="Permalink to &quot;📊 八、数据优化方法（必须做）&quot;">​</a></h1><p>每篇文章发布后，重点看三个指标：</p><p>1）点击率（标题是否有效） 2）收藏率（内容是否有用） 3）关注率（用户是否认可你）</p><p>优化逻辑：</p><ul><li>点击低 → 改标题</li><li>收藏低 → 内容不够实用</li><li>关注低 → 缺少价值感或信任感</li></ul><hr><h1 id="⚠️-九、最关键的一点-很多人会做错" tabindex="-1">⚠️ 九、最关键的一点（很多人会做错） <a class="header-anchor" href="#⚠️-九、最关键的一点-很多人会做错" aria-label="Permalink to &quot;⚠️ 九、最关键的一点（很多人会做错）&quot;">​</a></h1><p>你做的不是“AI内容号”，而是：</p><p>👉 <strong>“普通人如何用AI改变生活”的解决方案号</strong></p><p>如果你只发工具、发新闻、发教程，用户会走； 但如果你持续回答：</p><p>👉 “AI对你有什么影响” 👉 “你该怎么办”</p><p>用户就会留下。</p><hr><h1 id="🚀-最后一句总结" tabindex="-1">🚀 最后一句总结 <a class="header-anchor" href="#🚀-最后一句总结" aria-label="Permalink to &quot;🚀 最后一句总结&quot;">​</a></h1><p>这套矩阵本质就是：</p><p>👉 用趋势制造焦虑 👉 用教程提供方法 👉 用案例建立信任 👉 用赚钱推动行动 👉 用避坑延长生命周期</p>',91)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
